#include <stdio.h>

typedef struct {
    char name[20];
    int age;
} Crew;

int main(void) {
    int n;
    Crew crew[50];
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%19s %d", crew[i].name, &crew[i].age);
    }
    for (int i = 1; i < n; i++) {
        Crew current = crew[i];
        int j = i - 1;
        while (j >= 0 && crew[j].age > current.age) {
            crew[j + 1] = crew[j];
            j--;
        }
        crew[j + 1] = current;
    }
    for (int i = 0; i < n; i++) {
        printf("%s %d\n", crew[i].name, crew[i].age);
    }
    return 0;
}
